using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class ReefDaySix {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/DaySix";
 public static void Run(){Apply();Validate();Capture();}
 static void Info(GameObject go,string name,string fact,string audio,float range=3.2f){var info=go.GetComponent<ReefCreatureInfo>();if(!info)info=go.AddComponent<ReefCreatureInfo>();info.creatureName=name;info.fact=fact;info.narration=Resources.Load<AudioClip>(audio);info.observationRange=range;}
 public static void Apply(){var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var old=GameObject.Find("Day 6 open water and finale");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Day 6 open water and finale").transform;
  var material=AssetDatabase.LoadAssetAtPath<Material>(Folder+"/ReefShark.mat");if(!material){material=new Material(Shader.Find("Underwater/Reef Shark Skin"));AssetDatabase.CreateAsset(material,Folder+"/ReefShark.mat");}
  var mesh=SharkMesh();var saved=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/ReefShark.asset");if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}else{saved=mesh;AssetDatabase.CreateAsset(mesh,Folder+"/ReefShark.asset");}
  var shark=new GameObject("Distant reef shark");shark.transform.SetParent(root,false);shark.transform.position=new Vector3(19,-11,194);shark.AddComponent<MeshFilter>().sharedMesh=saved;shark.AddComponent<MeshRenderer>().sharedMaterial=material;shark.AddComponent<ReefSphereBody>().radius=1.9f;var life=shark.AddComponent<SeaLife>();life.kind="Reef shark";life.stationary=true;life.observationOnly=true;life.consequence=false;var actor=shark.AddComponent<OpenWaterShark>();actor.cautionVoice=Resources.Load<AudioClip>("DangerSharkPursuit");
  var trench=Array.Find(UnityEngine.Object.FindObjectsByType<SquidSwimmer>(FindObjectsSortMode.None),s=>s.name=="Giant squid distant silhouette");if(!trench)throw new Exception("Trench squid missing");DiverRevision.ConfigureSquid(trench,null);
  foreach(var turtle in UnityEngine.Object.FindObjectsByType<TurtleSwimmer>(FindObjectsSortMode.None))Info(turtle.gameObject,"Sea turtle","Sea turtles breathe air.","OpenWaterTurtleFact");
  foreach(var ray in UnityEngine.Object.FindObjectsByType<StingraySwimmer>(FindObjectsSortMode.None))Info(ray.gameObject,"Stingray","Its tail carries the defensive barb.","FinalRayFact");
  var source=Array.Find(UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None),a=>a.species==WreckCreature.Species.Grouper);var grouper=new GameObject("Calm finale grouper");grouper.transform.SetParent(root,false);grouper.transform.position=new Vector3(2,-7,225);grouper.transform.localScale=source.transform.localScale;grouper.AddComponent<MeshFilter>().sharedMesh=source.GetComponent<MeshFilter>().sharedMesh;grouper.AddComponent<MeshRenderer>().sharedMaterial=source.GetComponent<Renderer>().sharedMaterial;grouper.AddComponent<ReefSphereBody>().radius=.85f;var safe=grouper.AddComponent<SeaLife>();safe.kind="Grouper";safe.stationary=true;grouper.AddComponent<FishBodyMotion>();var cruiser=grouper.AddComponent<ReefCruiser>();cruiser.speed=.16f;cruiser.radius=1.8f;Info(grouper,"Grouper","Groupers are ambush predators.","WreckGrouperFact");
  var ending=root.gameObject.AddComponent<DiveEnding>();ending.endingVoice=Resources.Load<AudioClip>("CalmDiveEnding");
  Physics.SyncTransforms();foreach(var body in root.GetComponentsInChildren<ReefSphereBody>())if(!body.Clear(body.transform.position)&&!body.PlaceNear(body.transform.position))throw new Exception("Blocked final habitat animal "+body.name);
  foreach(string name in new[]{"DangerSharkPursuit","CalmDiveEnding","OpenWaterTurtleFact","OpenWaterSquidFact","FinalRayFact"}){var importer=AssetImporter.GetAtPath("Assets/Ocean/Resources/"+name+".wav") as AudioImporter;if(!importer)throw new Exception("Missing cue "+name);var samples=importer.defaultSampleSettings;samples.loadType=AudioClipLoadType.DecompressOnLoad;samples.compressionFormat=AudioCompressionFormat.PCM;importer.defaultSampleSettings=samples;importer.SaveAndReimport();}
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
 }
 static void Fin(ReefGeometry g,Vector3[] edge){Vector3 center=Vector3.zero;foreach(var p in edge)center+=p;center/=edge.Length;Vector3 normal=Vector3.Cross(edge[1]-edge[0],edge[2]-edge[0]).normalized*.012f;int a=g.Vertex(center+normal,Vector2.zero,Color.white),b=g.Vertex(center-normal,Vector2.zero,Color.white),start=b+1;foreach(var p in edge){g.Vertex(p+normal*.2f,Vector2.zero,Color.white);g.Vertex(p-normal*.2f,Vector2.zero,Color.white);}for(int i=0;i<edge.Length;i++){int j=start+i*2,k=start+(i+1)%edge.Length*2;g.Tri(a,j,k);g.Tri(b,k+1,j+1);g.Quad(j,j+1,k+1,k);}}
 static Mesh SharkMesh(){var g=new ReefGeometry();const int rings=100,sides=40;float[] stations={-1.65f,-1.35f,-1,-.5f,0,.5f,1,1.3f,1.55f};float[] widths={.025f,.055f,.10f,.19f,.28f,.29f,.22f,.13f,.005f};float[] heights={.025f,.055f,.10f,.19f,.24f,.23f,.16f,.075f,.005f};float Profile(float z,float[] values){for(int i=0;i<stations.Length-1;i++)if(z<=stations[i+1])return Mathf.Lerp(values[i],values[i+1],Mathf.SmoothStep(0,1,Mathf.InverseLerp(stations[i],stations[i+1],z)));return values[values.Length-1];}
  for(int i=0;i<=rings;i++){float z=Mathf.Lerp(-1.65f,1.55f,i/(float)rings);for(int j=0;j<=sides;j++){float a=j*Mathf.PI*2/sides;g.Vertex(new Vector3(Mathf.Cos(a)*Profile(z,widths),Mathf.Sin(a)*Profile(z,heights),z),new Vector2(j/(float)sides,i/(float)rings),Color.white);}}for(int i=0;i<rings;i++)for(int j=0;j<sides;j++){int a=i*(sides+1)+j;g.Quad(a,a+1,a+sides+2,a+sides+1);}
  Fin(g,new[]{new Vector3(0,.19f,.38f),new Vector3(0,.62f,-.12f),new Vector3(0,.55f,-.24f),new Vector3(0,.18f,-.47f)});Fin(g,new[]{new Vector3(0,.1f,-.82f),new Vector3(0,.28f,-1.03f),new Vector3(0,.09f,-1.17f)});
  for(int side=-1;side<=1;side+=2){Fin(g,new[]{new Vector3(side*.24f,-.09f,.54f),new Vector3(side*.92f,-.17f,-.11f),new Vector3(side*.8f,-.17f,-.25f),new Vector3(side*.22f,-.13f,.06f)});Fin(g,new[]{new Vector3(side*.16f,-.11f,-.46f),new Vector3(side*.38f,-.17f,-.82f),new Vector3(side*.1f,-.09f,-.8f)});g.Ellipsoid(new Vector3(side*.163f,.045f,1.18f),new Vector3(.018f,.021f,.026f),8,12);for(int i=0;i<5;i++)g.Tube(new[]{new Vector3(side*.26f,.055f,.52f-i*.045f),new Vector3(side*.283f,-.015f,.50f-i*.045f),new Vector3(side*.245f,-.10f,.48f-i*.045f)},new[]{.002f,.004f,.002f},5,new Color(.13f,.15f,.15f));}
  Fin(g,new[]{new Vector3(0,.01f,-1.32f),new Vector3(0,.69f,-1.77f),new Vector3(0,.8f,-1.95f),new Vector3(0,.15f,-1.77f),new Vector3(0,-.43f,-1.95f),new Vector3(0,-.31f,-1.67f),new Vector3(0,-.03f,-1.43f)});
  var mesh=g.Mesh("Smooth reef shark with swept fins and gill slits");var colors=mesh.colors;var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)if(Mathf.Abs(vertices[i].x)>.15f&&vertices[i].z>1.15f&&vertices[i].z<1.21f&&vertices[i].y>.02f&&vertices[i].y<.07f)colors[i]=new Color(.015f,.02f,.02f);mesh.colors=colors;var bounds=mesh.bounds;bounds.Expand(.4f);mesh.bounds=bounds;return mesh;
 }
 public static void Validate(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var shark=UnityEngine.Object.FindFirstObjectByType<OpenWaterShark>();if(!shark||!shark.cautionVoice||shark.cautionVoice.length>5)throw new Exception("Missing pursuit voice");var life=shark.GetComponent<SeaLife>();if(life.danger||life.consequence||life.grabbable||!life.observationOnly)throw new Exception("Shark must never punish touch");
  for(int i=0;i<120;i++)if(shark.Step(1f/30,shark.transform.position-Vector3.forward*10,Vector3.zero,true))throw new Exception("Stationary watching triggered caution");for(int i=0;i<120;i++)if(shark.Step(1f/30,shark.transform.position-Vector3.forward*10,Vector3.forward*.4f,true))throw new Exception("Slow swimming triggered caution");bool warned=false;for(int i=0;i<30;i++)warned|=shark.Step(1f/30,shark.transform.position-Vector3.forward*10,Vector3.forward*1.3f,true);if(!warned)throw new Exception("Pursuit did not caution");shark.MarkWarned();for(int i=0;i<90;i++)if(shark.Step(1f/30,shark.transform.position-Vector3.forward*10,Vector3.forward*1.3f,true))throw new Exception("Pursuit cue repeated without cooldown");
  float travel=0;for(int i=0;i<5400;i++){var before=shark.transform.position;shark.Step(1f/30,OceanWorld.Centers[6],Vector3.zero,true);travel+=Vector3.Distance(before,shark.transform.position);if(!shark.GetComponent<ReefSphereBody>().Clear(shark.transform.position))throw new Exception("Shark entered reef");}if(travel<20)throw new Exception("Shark stalled travel="+travel+" position="+shark.transform.position+" forward="+shark.transform.forward);
  var ending=UnityEngine.Object.FindFirstObjectByType<DiveEnding>();for(int i=0;i<100;i++)if(ending.Step(.1f,true,true))throw new Exception("Menu advanced ending");for(int i=0;i<100;i++)ending.Step(.1f,true,false);ending.Step(.1f,false,false);for(int i=0;i<190;i++)if(ending.Step(.1f,true,false))throw new Exception("Ending did not reset on early departure");for(int i=0;i<20;i++)ending.Step(.1f,true,false);if(!ending.Step(.1f,true,false))throw new Exception("Ending missing");ending.Complete();for(int i=0;i<600;i++)if(ending.Step(.1f,true,false))throw new Exception("Ending repeated");if(!ending.Completed||!ending.endingVoice)throw new Exception("Ending state lost");
  foreach(var ray in UnityEngine.Object.FindObjectsByType<StingraySwimmer>(FindObjectsSortMode.None)){if(!ray.SafeBodyTouch(ray.transform.TransformPoint(new Vector3(.6f,.05f,0)))||ray.SafeBodyTouch(ray.transform.TransformPoint(new Vector3(0,0,-1.5f))))throw new Exception("Ray body/tail overlap");for(int i=0;i<30;i++)ray.Step(1f/30,true);if(ray.TouchResponse<.9f)throw new Exception("Missing safe wing response");for(int i=0;i<120;i++)ray.Step(1f/30);if(ray.TouchResponse>.01f)throw new Exception("Wing response failed recovery");}
  EditorSceneManager.OpenScene(Scene);var passing=GameObject.Find("Giant squid distant silhouette").GetComponent<SquidSwimmer>();var recurring=passing.GetComponent<RecurringSquid>();if(!recurring||!recurring.EnterHabitat(6,OceanWorld.Centers[6]))throw new Exception("Single recurring squid missing");float squidTravel=0;for(int i=0;i<5400;i++){var before=passing.transform.position;passing.Step(1f/30);squidTravel+=Vector3.Distance(before,passing.transform.position);if(!passing.ClearPose(passing.transform.position,passing.transform.rotation))throw new Exception("Open water squid entered reef");}if(squidTravel<15)throw new Exception("Open water squid stalled");
  Debug.Log("DAY_SIX_VALIDATED sharkWatchSlowApproach=silent fastPursuit=cautionOnly cooldown=passed sharkTravel="+travel+" squidTravel="+squidTravel+" raySafeTouchRecovery=passed endingPauseResetPersistence=passed");ReefDayFive.Validate();
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders/DaySix");var camera=Camera.main;camera.fieldOfView=60;var atmosphere=UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>();foreach(string name in new[]{"Distant reef shark","Giant squid distant silhouette","Calm finale grouper"}){var t=GameObject.Find(name).transform;bool squid=name.Contains("squid");camera.transform.position=t.position+new Vector3(squid?12:3,squid?2:.7f,squid?8:2);camera.transform.LookAt(t.position+t.forward*(squid?-3:0));atmosphere.Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/DaySix/"+name.Replace(" ","_")+".png");}}
}
}
